from math import pi, fabs


class TriCalculator:

    DEGREES_TO_RADIANS = pi / 180
    TAYLOR_TERMS = 50
    SIN_TOLERANCE = 1e-15
    ROUNDING_PRECISION = 10

    def __init__(self):
        pass

    def cos(self, x):
        return round(self.taylor(x, self.TAYLOR_TERMS), self.ROUNDING_PRECISION)

    def factorial(self, a):
        result = 1
        for i in range(2, a + 1):
            result *= i
        return result

    def taylor(self, x, n):
        x = self.convert_to_radians(x)
        a = 1
        for k in range(1, n):
            term = (x ** (2 * k)) / self.factorial(2 * k)
            a += -1 if k % 2 != 0 else 1 * term
        return a

    def sin(self, x):
        x = self.convert_to_radians(x)
        total = 0
        term = x
        n = 1

        while fabs(term) >= self.SIN_TOLERANCE:
            total += term
            n += 1
            term = -term * x * x / (2 * n - 1) / (2 * n - 2)
        return round(total, self.ROUNDING_PRECISION)

    def tan(self, x):
        if self.cos(x) == 0:
            return False
        return round(self.sin(x) / self.cos(x), self.ROUNDING_PRECISION)

    def convert_to_radians(self, degrees):
        return degrees * self.DEGREES_TO_RADIANS
